/**
 * Shared Airpay admin datatable component.
 * @module     theme_airpayux/datatable
 * @copyright  2026 Airpay Payment Services
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define("theme_airpayux/datatable", [
    "core/ajax",
    "core/notification"
], function(Ajax, Notification) {
    "use strict";

    var instances = new WeakMap();

    var debounce = function(fn, ms) {
        var t;
        return function() {
            var args = arguments;
            clearTimeout(t);
            t = setTimeout(function() { fn.apply(null, args); }, ms);
        };
    };

    var escapeHtml = function(s) {
        if (s === null || s === undefined) return "";
        return String(s).replace(/[&<>"']/g, function(c) {
            return {"&": "&amp;", "<": "&lt;", ">": "&gt;",
                    '"': "&quot;", "'": "&#39;"}[c];
        });
    };

    function Datatable(root) {
        this.root = root;
        this.endpoint = root.dataset.endpoint;
        this.columns = JSON.parse(root.dataset.columns || "[]");
        this.perpage = parseInt(root.dataset.perpage || "25", 10);
        this.searchPlaceholder = root.dataset.searchPlaceholder || "Search…";
        this.actionsHtml = root.dataset.rowActions || "";
        this.selectable = root.dataset.selectable === "1";

        var firstSortable = this.columns.find(function(c) { return c.sortable; });
        this.state = {
            search: "",
            sort: firstSortable ? (firstSortable.sortkey || firstSortable.key) : "",
            sortcol: firstSortable ? firstSortable.key : "",
            sortdir: "asc",
            page: 0,
            filters: {},
            total: 0,
            rows: [],
            loading: false,
            selected: new Set()
        };

        this.render();
        this.attachHandlers();
        this.fetch();
    }

    Datatable.prototype.getSelected = function() { return Array.from(this.state.selected); };
    Datatable.prototype.clearSelection = function() {
        this.state.selected.clear();
        this.renderBody();
        this.fireSelectionChanged();
    };
    Datatable.prototype.fireSelectionChanged = function() {
        this.root.dispatchEvent(new CustomEvent("airpay:datatable:selection",
            {bubbles: true, detail: {selected: Array.from(this.state.selected)}}));
    };

    Datatable.prototype.render = function() {
        this.root.innerHTML =
            '<div class="airpay-datatable">' +
                '<div class="airpay-datatable__toolbar d-flex justify-content-between align-items-center mb-3 gap-2 flex-wrap">' +
                    '<div class="airpay-datatable__search position-relative" style="flex: 1; max-width: 380px;">' +
                        '<i class="fa fa-search position-absolute" style="top: 50%; left: 12px; transform: translateY(-50%); color: #888;"></i>' +
                        '<input type="search" class="form-control" placeholder="' + escapeHtml(this.searchPlaceholder) + '"' +
                               ' style="padding-left: 36px;" data-airpay-table-search>' +
                    '</div>' +
                    '<div class="airpay-datatable__meta small text-muted" data-airpay-table-meta></div>' +
                '</div>' +
                '<div class="card border-0 shadow-sm">' +
                    '<div class="table-responsive">' +
                        '<table class="table table-hover mb-0 align-middle">' +
                            '<thead style="background: var(--ap-color-primary, #0066A7); color: #fff;">' +
                                '<tr data-airpay-table-head></tr>' +
                            '</thead>' +
                            '<tbody data-airpay-table-body>' +
                                '<tr><td colspan="99" class="text-center py-5 text-muted">' +
                                    '<i class="fa fa-spinner fa-spin fa-2x d-block mb-2"></i> Loading…' +
                                '</td></tr>' +
                            '</tbody>' +
                        '</table>' +
                    '</div>' +
                    '<div class="card-body bg-light border-top d-flex justify-content-between align-items-center"' +
                         ' data-airpay-table-pager style="display: none !important;">' +
                        '<div class="small text-muted" data-airpay-table-pager-info></div>' +
                        '<div class="btn-group btn-group-sm" data-airpay-table-pager-buttons></div>' +
                    '</div>' +
                '</div>' +
            '</div>';
        this.renderHead();
    };

    Datatable.prototype.renderHead = function() {
        var self = this;
        var head = this.root.querySelector("[data-airpay-table-head]");
        var selectCol = this.selectable
            ? '<th style="width: 36px; padding-left: 12px;"><input type="checkbox" data-airpay-table-select-all></th>'
            : '';
        head.innerHTML = selectCol + this.columns.map(function(c) {
            var sortable = c.sortable ? "cursor: pointer;" : "";
            var arrow = "";
            if (c.key === self.state.sortcol) {
                arrow = self.state.sortdir === "asc"
                    ? ' <i class="fa fa-caret-up"></i>'
                    : ' <i class="fa fa-caret-down"></i>';
            }
            return '<th class="ps-3" style="' + sortable + ' font-weight: 600; font-size: 0.85rem;"'
                + (c.sortable ? ' data-airpay-table-sort="' + escapeHtml(c.key) + '"' : '')
                + '>' + escapeHtml(c.label) + arrow + '</th>';
        }).join("") + (this.actionsHtml
            ? '<th class="text-end pe-3" style="font-weight: 600; font-size: 0.85rem;">Actions</th>'
            : '');
    };

    Datatable.prototype.attachHandlers = function() {
        var self = this;
        var search = this.root.querySelector("[data-airpay-table-search]");
        search.addEventListener("input", debounce(function(e) {
            self.state.search = e.target.value;
            self.state.page = 0;
            self.fetch();
        }, 250));

        this.root.addEventListener("click", function(e) {
            var sortHead = e.target.closest("[data-airpay-table-sort]");
            if (sortHead) {
                var colKey = sortHead.dataset.airpayTableSort;
                var col = self.columns.find(function(c) { return c.key === colKey; });
                var sortBy = (col && col.sortkey) ? col.sortkey : colKey;
                if (self.state.sortcol === colKey) {
                    self.state.sortdir = (self.state.sortdir === "asc") ? "desc" : "asc";
                } else {
                    self.state.sortcol = colKey;
                    self.state.sort = sortBy;
                    self.state.sortdir = "asc";
                }
                self.state.page = 0;
                self.renderHead();
                self.fetch();
                return;
            }
            var pageBtn = e.target.closest("[data-airpay-table-page]");
            if (pageBtn) {
                e.preventDefault();
                self.state.page = parseInt(pageBtn.dataset.airpayTablePage, 10);
                self.fetch();
            }
        });

        this.root.addEventListener("change", function(e) {
            var sel = e.target.closest("[data-airpay-table-select]");
            if (sel) {
                var id = parseInt(sel.dataset.airpayTableSelect, 10);
                if (sel.checked) self.state.selected.add(id);
                else             self.state.selected.delete(id);
                self.fireSelectionChanged();
                return;
            }
            var all = e.target.closest("[data-airpay-table-select-all]");
            if (all) {
                if (all.checked) {
                    self.state.rows.forEach(function(r) { self.state.selected.add(r.id); });
                } else {
                    self.state.rows.forEach(function(r) { self.state.selected.delete(r.id); });
                }
                self.renderBody();
                self.fireSelectionChanged();
            }
        });
    };

    Datatable.prototype.fetch = function() {
        var self = this;
        if (this.state.loading) return;
        this.state.loading = true;

        var args = {
            search: this.state.search,
            sort: this.state.sort,
            sortdir: this.state.sortdir,
            page: this.state.page,
            perpage: this.perpage,
            filters: JSON.stringify(this.state.filters)
        };

        // Moodle's Ajax.call returns a jQuery deferred which does NOT
        // implement Promise.finally — we have to flip `loading = false`
        // in BOTH branches manually.
        Ajax.call([{methodname: this.endpoint, args: args}])[0]
            .then(function(response) {
                self.state.total = response.total || 0;
                self.state.rows = response.rows || [];
                self.renderBody();
                self.renderPager();
                self.renderMeta();
                self.root.dispatchEvent(new CustomEvent("airpay:datatable:rendered",
                    {bubbles: true, detail: self.state}));
                self.state.loading = false;
                return null;
            })
            .catch(function(e) {
                Notification.exception(e);
                self.root.querySelector("[data-airpay-table-body]").innerHTML =
                    '<tr><td colspan="99" class="text-center py-4 text-danger">Failed to load data. '
                    + escapeHtml(e.message || "") + '</td></tr>';
                self.state.loading = false;
            });
    };

    Datatable.prototype.renderBody = function() {
        var self = this;
        var body = this.root.querySelector("[data-airpay-table-body]");
        var totalCols = this.columns.length + (this.actionsHtml ? 1 : 0) + (this.selectable ? 1 : 0);
        if (this.state.rows.length === 0) {
            var msg = this.state.search
                ? 'No results for "' + escapeHtml(this.state.search) + '"'
                : "No records found";
            body.innerHTML = '<tr><td colspan="' + totalCols + '" class="text-center py-5 text-muted">'
                + '<i class="fa fa-inbox fa-2x d-block mb-2"></i>' + msg + '</td></tr>';
            return;
        }
        body.innerHTML = this.state.rows.map(function(row) {
            var id = row.id;
            var isChecked = self.state.selected.has(id);
            var checkboxCell = self.selectable
                ? '<td style="padding-left: 12px;"><input type="checkbox" data-airpay-table-select="'
                    + escapeHtml(id) + '" ' + (isChecked ? 'checked' : '') + '></td>'
                : '';
            var cells = self.columns.map(function(c) {
                var val = row[c.key];
                if (c.format === "badge") {
                    var cls = row[c.key + "_class"] || "badge-secondary";
                    val = '<span class="badge ' + escapeHtml(cls) + '">' + escapeHtml(val) + '</span>';
                } else if (c.format === "html") {
                    val = val || "";
                } else {
                    val = escapeHtml(val);
                }
                return '<td class="ps-3">' + val + '</td>';
            }).join("");
            var actionCell = "";
            if (self.actionsHtml || row.actions) {
                var html = row.actions || self.actionsHtml.replace(/\{\{(\w+)\}\}/g, function(m, key) {
                    return escapeHtml(row[key] != null ? row[key] : "");
                });
                actionCell = '<td class="text-end pe-3">' + html + '</td>';
            }
            var rowAttrs = 'data-row-id="' + escapeHtml(id != null ? id : "") + '"' + (isChecked ? ' class="table-active"' : '');
            return '<tr ' + rowAttrs + '>' + checkboxCell + cells + actionCell + '</tr>';
        }).join("");
    };

    Datatable.prototype.renderMeta = function() {
        var meta = this.root.querySelector("[data-airpay-table-meta]");
        var start = this.state.page * this.perpage + 1;
        var end = Math.min(start + this.state.rows.length - 1, this.state.total);
        meta.textContent = this.state.total > 0
            ? start + "–" + end + " of " + this.state.total.toLocaleString()
            : "";
    };

    Datatable.prototype.renderPager = function() {
        var pager = this.root.querySelector("[data-airpay-table-pager]");
        var info = this.root.querySelector("[data-airpay-table-pager-info]");
        var buttons = this.root.querySelector("[data-airpay-table-pager-buttons]");

        var totalPages = Math.ceil(this.state.total / this.perpage);
        if (totalPages <= 1) {
            pager.style.display = "none";
            return;
        }
        pager.style.display = "";
        info.textContent = "Page " + (this.state.page + 1) + " of " + totalPages;

        var cur = this.state.page;
        var pages = [];
        pages.push({label: "«", page: 0, disabled: cur === 0});
        pages.push({label: "‹", page: Math.max(0, cur - 1), disabled: cur === 0});
        var start = Math.max(0, cur - 2);
        var end = Math.min(totalPages, cur + 3);
        for (var p = start; p < end; p++) {
            pages.push({label: String(p + 1), page: p, active: p === cur});
        }
        pages.push({label: "›", page: Math.min(totalPages - 1, cur + 1), disabled: cur >= totalPages - 1});
        pages.push({label: "»", page: totalPages - 1, disabled: cur >= totalPages - 1});

        buttons.innerHTML = pages.map(function(p) {
            return '<button type="button" class="btn btn-' + (p.active ? "primary" : "outline-secondary") + ' btn-sm"'
                + ' data-airpay-table-page="' + p.page + '"' + (p.disabled ? " disabled" : "") + ">"
                + escapeHtml(p.label) + "</button>";
        }).join("");
    };

    Datatable.prototype.refresh = function() { this.fetch(); };

    Datatable.prototype.setFilter = function(key, value) {
        if (value === "" || value === null || value === undefined) {
            delete this.state.filters[key];
        } else {
            this.state.filters[key] = value;
        }
        this.state.page = 0;
        this.fetch();
    };

    return {
        init: function() {
            document.querySelectorAll("[data-airpay-table]").forEach(function(root) {
                if (instances.has(root)) return;
                instances.set(root, new Datatable(root));
            });
        },
        getInstance: function(root) { return instances.get(root); }
    };
});
